import{_ as a,o as l,c as i,a4 as t}from"./chunks/framework.DzJZdBQK.js";const r="/assets/olap.7dp08FD8.png",b=JSON.parse('{"title":"基于ElasticSearch的OLAP框架思路","description":"","frontmatter":{"date":"2018-09-28T11:22:43","title":"基于ElasticSearch的OLAP框架思路","categories":["ElasticSearch","OLAP"],"tags":["ElasticSearch","OLAP"]},"headers":[{"level":2,"title":"联机分析处理（On-Line Analytical Processing，OLAP）","slug":"联机分析处理-on-line-analytical-processing-olap","link":"#联机分析处理-on-line-analytical-processing-olap","children":[]},{"level":2,"title":"维（Dimension）","slug":"维-dimension","link":"#维-dimension","children":[]},{"level":2,"title":"维的层次（Level）","slug":"维的层次-level","link":"#维的层次-level","children":[]},{"level":2,"title":"维的成员（Member）","slug":"维的成员-member","link":"#维的成员-member","children":[]},{"level":2,"title":"度量（Measure）","slug":"度量-measure","link":"#度量-measure","children":[]},{"level":2,"title":"指标（Quota），补充","slug":"指标-quota-补充","link":"#指标-quota-补充","children":[]},{"level":2,"title":"典型操作","slug":"典型操作","link":"#典型操作","children":[{"level":3,"title":"钻取","slug":"钻取","link":"#钻取","children":[]},{"level":3,"title":"切片和切块","slug":"切片和切块","link":"#切片和切块","children":[]},{"level":3,"title":"旋转","slug":"旋转","link":"#旋转","children":[]}]},{"level":2,"title":"ES文档和多维数据集","slug":"es文档和多维数据集","link":"#es文档和多维数据集","children":[{"level":3,"title":"ES的存储结构","slug":"es的存储结构","link":"#es的存储结构","children":[]},{"level":3,"title":"多维联机分析处理（MOLAP）","slug":"多维联机分析处理-molap","link":"#多维联机分析处理-molap","children":[]}]},{"level":2,"title":"数据建模","slug":"数据建模","link":"#数据建模","children":[{"level":3,"title":"维度管理","slug":"维度管理","link":"#维度管理","children":[]},{"level":3,"title":"元数据管理","slug":"元数据管理","link":"#元数据管理","children":[]},{"level":3,"title":"映射管理","slug":"映射管理","link":"#映射管理","children":[]}]},{"level":2,"title":"数据ETL","slug":"数据etl","link":"#数据etl","children":[{"level":3,"title":"首次加载","slug":"首次加载","link":"#首次加载","children":[]},{"level":3,"title":"刷新加载","slug":"刷新加载","link":"#刷新加载","children":[]},{"level":3,"title":"数据转换","slug":"数据转换","link":"#数据转换","children":[]}]},{"level":2,"title":"统计分析","slug":"统计分析","link":"#统计分析","children":[]},{"level":2,"title":"数据展示","slug":"数据展示","link":"#数据展示","children":[]},{"level":2,"title":"参考连接","slug":"参考连接","link":"#参考连接","children":[]}],"relativePath":"posts/bigdata/es/olap-1.md","filePath":"posts/bigdata/es/olap-1.md"}'),n={name:"posts/bigdata/es/olap-1.md"};function o(s,e,h,c,d,p){return l(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="olap基本概念" tabindex="-1">OLAP基本概念 <a class="header-anchor" href="#olap基本概念" aria-label="Permalink to &quot;OLAP基本概念&quot;">​</a></h1><h2 id="联机分析处理-on-line-analytical-processing-olap" tabindex="-1">联机分析处理（On-Line Analytical Processing，OLAP） <a class="header-anchor" href="#联机分析处理-on-line-analytical-processing-olap" aria-label="Permalink to &quot;联机分析处理（On-Line Analytical Processing，OLAP）&quot;">​</a></h2><p>联机分析处理的概念最早是由关系数据库之父爱德华·库德（E·F·Codd）博士于1993年提出的，是一种用于组织大型商务数据库和支持商务智能的技术。OLAP 数据库分为一个或多个多维数据集，每个多维数据集都由多维数据集管理员组织和设计以适应用户检索和分析数据的方式，从而更易于创建和使用所需的数据透视表和数据透视图。</p><h2 id="维-dimension" tabindex="-1">维（Dimension） <a class="header-anchor" href="#维-dimension" aria-label="Permalink to &quot;维（Dimension）&quot;">​</a></h2><p>是人们观察数据的特定角度，是考虑问题时的一类属性，属性集合构成一个维（时间维、地理维等）。</p><h2 id="维的层次-level" tabindex="-1">维的层次（Level） <a class="header-anchor" href="#维的层次-level" aria-label="Permalink to &quot;维的层次（Level）&quot;">​</a></h2><p>人们观察数据的某个特定角度（即某个维）还可以存在细节程度不同的各个描述方面（时间维：日期、月份、季度、年）。</p><h2 id="维的成员-member" tabindex="-1">维的成员（Member） <a class="header-anchor" href="#维的成员-member" aria-label="Permalink to &quot;维的成员（Member）&quot;">​</a></h2><p>维的一个取值，是数据项在某维中位置的描述。（“某年某月某日”是在时间维上位置的描述）。</p><h2 id="度量-measure" tabindex="-1">度量（Measure） <a class="header-anchor" href="#度量-measure" aria-label="Permalink to &quot;度量（Measure）&quot;">​</a></h2><p>多维数组的取值。（2000年1月，上海，笔记本电脑，$100000）。</p><h2 id="指标-quota-补充" tabindex="-1">指标（Quota），补充 <a class="header-anchor" href="#指标-quota-补充" aria-label="Permalink to &quot;指标（Quota），补充&quot;">​</a></h2><p>可度量的属性。一般为某种值，如费用，入院人次。</p><h2 id="典型操作" tabindex="-1">典型操作 <a class="header-anchor" href="#典型操作" aria-label="Permalink to &quot;典型操作&quot;">​</a></h2><p>OLAP的基本多维分析操作有钻取（Drill-up和Drill-down）、切片（Slice）和切块（Dice）、以及旋转（Pivot）等。</p><h3 id="钻取" tabindex="-1">钻取 <a class="header-anchor" href="#钻取" aria-label="Permalink to &quot;钻取&quot;">​</a></h3><p>是改变维的层次，变换分析的粒度。它包括向下钻取（Drill-down）和向上钻取（Drill-up）/上卷(Roll-up)。Drill- up是在某一维上将低层次的细节数据概括到高层次的汇总数据，或者减少维数；而Drill-down则相反，它从汇总数据深入到细节数据进行观察或增加新维。</p><h3 id="切片和切块" tabindex="-1">切片和切块 <a class="header-anchor" href="#切片和切块" aria-label="Permalink to &quot;切片和切块&quot;">​</a></h3><p>是在一部分维上选定值后，关心度量数据在剩余维上的分布。如果剩余的维只有两个，则是切片；如果有三个或以上，则是切块。</p><h3 id="旋转" tabindex="-1">旋转 <a class="header-anchor" href="#旋转" aria-label="Permalink to &quot;旋转&quot;">​</a></h3><p>是变换维的方向，即在表格中重新安排维的放置（例如行列互换）。</p><h1 id="elasticsearch" tabindex="-1">ElasticSearch <a class="header-anchor" href="#elasticsearch" aria-label="Permalink to &quot;ElasticSearch&quot;">​</a></h1><p>Apache Lucene™可能是目前存在的，不论开源还是私有的，拥有最先进，高性能和全功能搜索引擎功能的库。但Lucene是很复杂的。 Elasticsearch是一个使用Java编写的开源的搜索引擎，它的内部使用 Lucene 做索引与搜索，但是它的目标是使全文检索变得简单， 通过隐藏 Lucene 的复杂性，取而代之的提供一套简单一致的 RESTful API。</p><p>然而，Elasticsearch不仅仅是 Lucene，并且也不仅仅只是一个全文搜索引擎。 它可以被下面这样准确的形容：</p><ul><li>一个分布式的实时文档存储，每个字段可以被索引与搜索</li><li>一个分布式实时分析搜索引擎</li><li>能胜任上百个服务节点的扩展，并支持PB级别的结构化或者非结构化数据</li></ul><p>Elasticsearch将所有的功能打包成一个单独的服务，这样你可以通过程序去访问它提供的简单的RESTful API服务， 不论你是使用自己喜欢的编程语言还是直接使用命令行。</p><p>Elasticsearch是一个实时的分布式搜索分析引擎， 它能让你以一个之前从未有过的速度和规模，去探索你的数据。 它被用作全文检索、结构化搜索、分析以及这三个功能的组合：</p><ul><li>Wikipedia 使用 Elasticsearch 提供带有高亮片段的全文搜索，还有 search-as-you-type 和 did-you-mean 的建议。</li><li>卫报 使用 Elasticsearch 将网络社交数据结合到访客日志中，实时的给它的编辑们提供公众对于新文章的反馈。</li><li>Stack Overflow 将地理位置查询融入全文检索中去，并且使用 more-like-this 接口去查找相关的问题与答案。</li><li>GitHub 使用 Elasticsearch 对1300亿行代码进行查询。</li></ul><h2 id="es文档和多维数据集" tabindex="-1">ES文档和多维数据集 <a class="header-anchor" href="#es文档和多维数据集" aria-label="Permalink to &quot;ES文档和多维数据集&quot;">​</a></h2><h3 id="es的存储结构" tabindex="-1">ES的存储结构 <a class="header-anchor" href="#es的存储结构" aria-label="Permalink to &quot;ES的存储结构&quot;">​</a></h3><p>ES文档通过JSON格式来表示。文档是可以被索引的基本单元，文档需要索引需要指定类型。ES能支持索引的数据类型有，其中的数组类型，对象类型和内嵌类型的支持，使得ES能存储更复杂的文档。</p><h3 id="多维联机分析处理-molap" tabindex="-1">多维联机分析处理（MOLAP） <a class="header-anchor" href="#多维联机分析处理-molap" aria-label="Permalink to &quot;多维联机分析处理（MOLAP）&quot;">​</a></h3><p>MOLAP将OLAP分析所用到的多维数据物理上存储为多维数组的形式，形成“立方体”的结构。维的属性值被映射成多维数组的下标值或下标的范围，而总结数据作为多维数组的值存储在数组的单元中。由于MOLAP采用了新的存储结构，从物理层实现起，因此又称为物理OLAP（PhysicalOLAP）；而 ROLAP主要通过一些软件工具或中间软件实现，物理层仍采用关系数据库的存储结构，因此称为虚拟OLAP（VirtualOLAP）。</p><p>我们可以看到基于复杂数据类型（Complex datatypes）构建的ES文档与MOLAP的概念是非常接近的，利用ElasticSearch的聚合的能力，我们能相对简单的实现OLAP框架。</p><h1 id="方案" tabindex="-1">方案 <a class="header-anchor" href="#方案" aria-label="Permalink to &quot;方案&quot;">​</a></h1><p>要实现整个OLAP框架主要需要处理以下几个环节</p><ol><li>数据建模</li><li>数据ETL</li><li>数据分析</li><li>数据展示</li></ol><p>大致思路如下： <img src="'+r+'" alt="OLAP"></p><h2 id="数据建模" tabindex="-1">数据建模 <a class="header-anchor" href="#数据建模" aria-label="Permalink to &quot;数据建模&quot;">​</a></h2><p>数据建模就是建立多维数据集的过程，同时为了能更有效的利用ES的索引，不建议过深的JSON层次，所以对应到维度建模时采用的是星形模式。</p><p>正常情况，是先进行数据建模，之后才能进行数据ETL，首先需要知道抽取的源数据的结构，即数据元数据之后，才能进一步分析数据模型。对于ES来说，实际上就是建立Index/Type的过程。</p><h3 id="维度管理" tabindex="-1">维度管理 <a class="header-anchor" href="#维度管理" aria-label="Permalink to &quot;维度管理&quot;">​</a></h3><h3 id="元数据管理" tabindex="-1">元数据管理 <a class="header-anchor" href="#元数据管理" aria-label="Permalink to &quot;元数据管理&quot;">​</a></h3><p>元数据管理维护了原始数据的元数据结构，简单来说就是原始数据有哪些库，哪些表，表之间有什么关系。</p><h3 id="映射管理" tabindex="-1">映射管理 <a class="header-anchor" href="#映射管理" aria-label="Permalink to &quot;映射管理&quot;">​</a></h3><p>映射管理是指定了需要抽取的数据范围及方法和确定了多维数据集的模型。</p><h2 id="数据etl" tabindex="-1">数据ETL <a class="header-anchor" href="#数据etl" aria-label="Permalink to &quot;数据ETL&quot;">​</a></h2><p>正常情况，是先进行数据建模，之后才能进行数据ETL，而实际过程中，是一般需要知道源数据的结构，即数据元数据之后，才能进一步分析数据模型。</p><p>数据ETL，实质就是从各个数据源提取数据，对数据进行转换，并最终加载填充数据到数据仓库维度建模后的表中。只有当多维数据集被填充好，ETL工作才算完成。</p><p>数据加载主要分为两种，一种是首次加载，一种是刷新加载（增量加载）。当前产品中主要涉及两种数据库，Mysql和Hbase。</p><h3 id="首次加载" tabindex="-1">首次加载 <a class="header-anchor" href="#首次加载" aria-label="Permalink to &quot;首次加载&quot;">​</a></h3><p>通过Quartz Job或MapRedurce Job将数据转换为Kafka消息，由数据加载组件来进行数据处理。</p><h3 id="刷新加载" tabindex="-1">刷新加载 <a class="header-anchor" href="#刷新加载" aria-label="Permalink to &quot;刷新加载&quot;">​</a></h3><p>通过扩展mysql-binlog-connector-java和HBase Side-Effect Processor，可以实现数据的实时增量更新。本方案中通过Kafka消息中间件来统一转发不同类型的数据更新，此处需要定义好Kafka的消息格式，以便数据加载组件能较简单的处理数据。</p><h3 id="数据转换" tabindex="-1">数据转换 <a class="header-anchor" href="#数据转换" aria-label="Permalink to &quot;数据转换&quot;">​</a></h3><p>转换步骤主要是指对提取好了的数据的结构进行转换，以满足目标数据仓库模型的过程。此外，转换过程也负责数据质量工作，这部分也被称为数据清洗(data cleaning)。转换过程可以通过逐步实现转换算法，动态上线的方式进行。</p><h2 id="统计分析" tabindex="-1">统计分析 <a class="header-anchor" href="#统计分析" aria-label="Permalink to &quot;统计分析&quot;">​</a></h2><p>统计分析其实就是从事实表中统计任意组合维度的指标，也就是过滤、分组、聚合，其中，聚合除了一般的SUM、COUNT、AVG、MAX、MIN等，还有一个重要的COUNT(DISTINCT)。ElasticSearch本来就是做实时搜索的，过滤自然不是问题，现在也支持各种聚合以及Pipeline aggregations（相当于SQL子查询的功能）。</p><p>统计分析是根据模板配置和页面操作时的条件生成ES语法，执行语法，返回结果数据的过程。从表面看，该过程不难，然而为了生成的ES语法的准确性，ES语法的生成引擎是非常重要的一个环节，通过在模板管理来增加一些配置来辅助ES的语法生成，如行维度，列维度，维的层次等等。</p><h2 id="数据展示" tabindex="-1">数据展示 <a class="header-anchor" href="#数据展示" aria-label="Permalink to &quot;数据展示&quot;">​</a></h2><p>通过模板的动态配置，利用Echart和Vue可以实现，动态布局和各种仪表盘的展示，这部分内容也可参看Kibana。</p><h1 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h1><p>ES的文档结构符合MOLAP的概念，它提供的聚合功能可以实现OLAP的各种操作，基于Lucene和分布式架构在性能上也能得到保障。通过定义一定的规则和开发一系列的辅助功能，可比较容易的实现一套通用的实时OLAP的框架。本文主要讲解的是基于ES构建OLAP框架的思路，而非完整的构建方案。</p><h2 id="参考连接" tabindex="-1">参考连接 <a class="header-anchor" href="#参考连接" aria-label="Permalink to &quot;参考连接&quot;">​</a></h2><ul><li>联机分析处理</li><li>Elasticsearch Basic Concepts</li><li><a href="https://www.elastic.co/products/hadoop" target="_blank" rel="noreferrer">https://www.elastic.co/products/hadoop</a></li><li>Hbase Indexer SEP</li><li>使用ElasticSearch作为大数据平台的实时OLAP框架</li><li><a href="https://blog.csdn.net/fighting_one_piece/article/details/51765383" target="_blank" rel="noreferrer">https://blog.csdn.net/fighting_one_piece/article/details/51765383</a></li><li><a href="https://yq.aliyun.com/articles/575991" target="_blank" rel="noreferrer">https://yq.aliyun.com/articles/575991</a></li><li>Mapping Types</li></ul>',65)])])}const P=a(n,[["render",o]]);export{b as __pageData,P as default};
